package com.jebscape.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.experimental.Accessors;

@Accessors(chain = true)
@Data
public class RuneLiteEntityOpsDefinition
{
	public List<Op> ops = new ArrayList<>();
	public List<List<SubOp>> subOps = new ArrayList<>();
	public List<List<ConditionalOp>> conditionalOps = new ArrayList<>();
	public List<Map<Integer, List<ConditionalSubOp>>> conditionalSubOps = new ArrayList<>();

	public RuneLiteEntityOpsDefinition setOp(int index, String text)
	{
		for (; this.ops.size() <= index; this.ops.add(null)) ;
		this.ops.set(index, new RuneLiteEntityOpsDefinition.Op(text));

		return this;
	}

	public RuneLiteEntityOpsDefinition setSubOp(int index, int subID, String text)
	{
		for (; this.subOps.size() <= index; this.subOps.add(new ArrayList<>())) ;
		this.subOps.get(index).add(new RuneLiteEntityOpsDefinition.SubOp(text, subID));

		return this;
	}

	public RuneLiteEntityOpsDefinition setConditionalOp(int index, String text, int varpID, int varbitID, int minValue, int maxValue)
	{
		for (; this.conditionalOps.size() <= index; this.conditionalOps.add(new ArrayList<>())) ;
		this.conditionalOps.get(index).add(new RuneLiteEntityOpsDefinition.ConditionalOp(text, varpID, varbitID, minValue, maxValue));

		return this;
	}

	public RuneLiteEntityOpsDefinition setConditionalSubOp(int index, int subID, String text, int varpID, int varbitID, int minValue, int maxValue)
	{
		for (; this.conditionalSubOps.size() <= index; this.conditionalSubOps.add(null)) ;

		Map<Integer, List<ConditionalSubOp>> map = this.conditionalSubOps.get(index);
		if (map == null)
		{
			this.conditionalSubOps.set(index, map = new HashMap<>());
		}

		List<ConditionalSubOp> list = map.computeIfAbsent(subID, k -> new ArrayList<>());
		list.add(new RuneLiteEntityOpsDefinition.ConditionalSubOp(text, subID, varpID, varbitID, minValue, maxValue));

		return this;
	}

	@AllArgsConstructor
	public static class Op
	{
		public String text;
	}

	public static class SubOp extends Op
	{
		public int subID;

		public SubOp(String text, int subID)
		{
			super(text);

			this.subID = subID;
		}
	}

	@Data
	public static class ConditionalOp extends Op
	{
		public int varpID;
		public int varbitID;
		public int minValue;
		public int maxValue;

		public ConditionalOp(String text, int varpID, int varbitID, int minValue, int maxValue)
		{
			super(text);

			this.varpID = varpID;
			this.varbitID = varbitID;
			this.minValue = minValue;
			this.maxValue = maxValue;
		}
	}

	@Data
	public static class ConditionalSubOp extends ConditionalOp
	{
		public int subID;

		public ConditionalSubOp(String text, int subID, int varpID, int varbitID, int minValue, int maxValue)
		{
			super(text, varpID, varbitID, minValue, maxValue);

			this.subID = subID;
		}
	}
}

