package com.jebscape.core;

public class RuneLiteEntityOpsLoader
{
	public void decodeOp(RuneLiteEntityOpsDefinition ops, RuneLiteInputStream is, int index)
	{
		String text = is.readString();
		if (!text.equalsIgnoreCase("Hidden"))
		{
			ops.setOp(index, text);
		}
	}

	public void decodeSubOp(RuneLiteEntityOpsDefinition ops, RuneLiteInputStream is)
	{
		int index = is.readUnsignedByte();
		int subID = is.readUnsignedByte();
		String text = is.readString();
		ops.setSubOp(index, subID, text);
	}

	public void decodeConditionalOp(RuneLiteEntityOpsDefinition ops, RuneLiteInputStream is)
	{
		int index = is.readUnsignedByte();
		int varp = is.readUnsignedShort();
		int varb = is.readUnsignedShort();
		int min = is.readInt();
		int max = is.readInt();
		String text = is.readString();

		ops.setConditionalOp(index, text, varp, varb, min, max);
	}

	public void decodeConditionalSubOp(RuneLiteEntityOpsDefinition ops, RuneLiteInputStream is)
	{
		int index = is.readUnsignedByte();
		int subID = is.readUnsignedShort();
		int varp = is.readUnsignedShort();
		int varb = is.readUnsignedShort();
		int min = is.readInt();
		int max = is.readInt();
		String text = is.readString();

		ops.setConditionalSubOp(index, subID, text, varp, varb, min, max);
	}
}

